  display: block;
  font-size: var(--font-size-base);
  color: var(--color-primary);
  font-weight: 600;
}

.rooms-amenities-title {
  font-size: var(--font-size-base);
  margin-bottom: var(--spacing-sm);
  margin-top: var(--spacing-md);
}

.amenity-list {
  margin-bottom: var(--spacing-md);
}

.rooms-price-section {
  margin-top: auto;
  padding-top: var(--spacing-md);
  border-top: 1px solid var(--color-border);
}

.rooms-book-btn {
  width: 100%;
  margin-top: var(--spacing-md);
  min-height: 44px;
}

.rooms-features-box {
  padding: var(--spacing-lg);
  background-color: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
}

.rooms-features-box h3 {
  margin-bottom: var(--spacing-md);
}

.rooms-booking-promo {
  text-align: center;
  padding: var(--spacing-lg);
  background-color: #fff;
  border-radius: var(--radius);
  border: 2px solid var(--color-accent);
}

.rooms-booking-promo h2 {
  margin-bottom: var(--spacing-md);
}

.rooms-booking-promo p {
  margin-bottom: var(--spacing-md);
  font-size: var(--font-size-lg);
  color: var(--color-text-light);
}

.rooms-booking-promo .button {
  margin-top: var(--spacing-md);
}

@media (max-width: 600px) {
  .grid-3 {
    grid-template-columns: 1fr;
  }

  .rooms-details {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .rooms-booking-promo .button {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .grid-3 {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  }
}

.gallery-intro {
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
  background-color: var(--color-bg-alt);
}

.gallery-intro p {
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  font-size: var(--font-size-lg);
  color: var(--color-text-light);
}

.gallery-grid {
  display: grid;
  gap: var(--spacing-md);
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
}

.gallery-item {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.gallery-item:hover {
  transform: scale(1.02);
  box-shadow: var(--shadow-lg);
}

.gallery-item img {
  display: block;
  width: 100%;
  height: 300px;
  object-fit: cover;
  transition: filter 0.3s ease;
}

.gallery-item:hover img {
  filter: brightness(0.9);
}

.gallery-item figcaption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.8), rgba(0, 0, 0, 0));
  color: #fff;
  padding: 1rem var(--spacing-md) var(--spacing-md);
  font-family: var(--font-family-serif);
  font-size: var(--font-size-base);
  font-weight: 600;
}

.gallery-grid-tall .gallery-item-tall img {
  height: 400px;
}

@media (min-width: 601px) {
  .gallery-grid {
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  }

  .gallery-grid-tall {
    grid-template-columns: repeat(3, 1fr);
  }

  .gallery-grid-tall .gallery-item-tall {
    grid-row: span 2;
  }

  .gallery-grid-tall .gallery-item-tall img {
    height: 616px;
  }
}

@media (max-width: 600px) {
  .gallery-grid {
    grid-template-columns: 1fr;
  }

  .gallery-item img {
    height: 250px;
  }

  .gallery-grid-tall {
    grid-template-columns: 1fr;
  }

  .gallery-grid-tall .gallery-item-tall img {
    height: 250px;
  }
}

.activities-card {
  display: flex;
  flex-direction: column;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.activities-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
}

.activities-icon {
  font-size: 3rem;
  text-align: center;
  padding: var(--spacing-lg) var(--spacing-md) var(--spacing-md);
  background: linear-gradient(135deg, rgba(26, 71, 42, 0.08), rgba(212, 165, 116, 0.08));
  flex-shrink: 0;
}

.activities-card .card-body {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.activities-card h3 {
  margin-bottom: var(--spacing-sm);
}

.activities-card p {
  flex-grow: 1;
  margin-bottom: var(--spacing-md);
}

.activities-meta {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
  font-size: var(--font-size-sm);
  color: var(--color-text-light);
  padding-top: var(--spacing-sm);
  border-top: 1px solid var(--color-border);
}

.activities-difficulty,
.activities-duration {
  display: block;
}

.activities-difficulty::before {
  content: "⚡ ";
}

.activities-duration::before {
  content: "⏱ ";
}

.activities-intro {
  background: linear-gradient(135deg, rgba(26, 71, 42, 0.05), rgba(212, 165, 116, 0.05));
  border-left: 4px solid var(--color-accent-dark);
}

.activities-intro p {
  font-size: var(--font-size-lg);
  color: var(--color-text);
  margin-bottom: 0;
}

.activities-booking-info {
  background-color: #fff;
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  border: 1px solid var(--color-border);
}

.activities-booking-info h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-md);
}

.activities-booking-steps {
  list-style-position: inside;
  color: var(--color-text-light);
  counter-reset: step-counter;
  list-style: none;
  padding: 0;
}

.activities-booking-steps li {
  padding: 0.5rem 0 0.5rem 1.5rem;
  position: relative;
  margin-bottom: 0.5rem;
}

.activities-booking-steps li::before {
  content: counter(step-counter);
  counter-increment: step-counter;
  position: absolute;
  left: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.25rem;
  height: 1.25rem;
  background-color: var(--color-accent);
  color: var(--color-primary);
  border-radius: 50%;
  font-size: 0.75rem;
  font-weight: bold;
}

.activities-checklist {
  list-style: none;
  padding: 0;
  color: var(--color-text-light);
}

.activities-checklist li {
  padding: 0.5rem 0 0.5rem 1.75rem;
  position: relative;
  margin-bottom: 0.5rem;
}

.activities-checklist li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: bold;
  font-size: 1.25rem;
}

.activities-contact-box {
  background-color: var(--color-primary);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  margin-top: var(--spacing-lg);
  text-align: center;
}

.activities-contact-box h3 {
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-md);
}

.activities-contact-box p {
  margin-bottom: var(--spacing-md);
  font-size: var(--font-size-base);
}

.activities-contact-box strong {
  color: var(--color-accent-on-dark);
}

.activities-contact-box .button {
  background-color: var(--color-accent-dark);
  border-color: var(--color-accent-dark);
  color: #fff;
  margin-top: var(--spacing-md);
}

.activities-contact-box .button:hover {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-primary);
}

@media (max-width: 600px) {
  .activities-icon {
    font-size: 2.5rem;
    padding: var(--spacing-md) var(--spacing-md) var(--spacing-sm);
  }

  .activities-meta {
    font-size: var(--font-size-sm);
  }

  .activities-contact-box {
    padding: var(--spacing-md);
  }

  .activities-contact-box .button {
    width: 100%;
  }

  .grid-2 {
    grid-template-columns: 1fr;
  }
}

@media (min-width: 601px) {
  .activities-booking-info {
    min-height: 100%;
  }
}

.contact-main {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.contact-wrapper {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xxl);
  align-items: start;
}

.contact-form-section {
  grid-column: 1;
}

.contact-form-section h2 {
  margin-bottom: var(--spacing-md);
}

.contact-form {
  background-color: #fff;
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
}

.contact-form .form-group {
  margin-bottom: var(--spacing-md);
}

.contact-form button {
  width: 100%;
  margin-top: var(--spacing-md);
}

.contact-info-section {
  grid-column: 2;
}

.contact-details h2 {
  margin-bottom: var(--spacing-lg);
}

.contact-card {
  background-color: var(--color-bg-alt);
  padding: var(--spacing-md);
  border-radius: var(--radius);
  margin-bottom: var(--spacing-md);
  border-left: 4px solid var(--color-accent-dark);
}

.contact-card h3 {
  font-size: var(--font-size-lg);
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary);
}

.contact-card p {
  color: var(--color-text);
  margin-bottom: 0;
  font-size: var(--font-size-base);
}

.contact-card a {
  color: var(--color-primary-light);
  word-break: break-all;
}

.contact-hours {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.contact-hours h2 {
  text-align: center;
  margin-bottom: var(--spacing-xxl);
}

.hours-wrapper {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-lg);
}

.hours-card {
  background-color: #fff;
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
}

.hours-card h3 {
  color: var(--color-primary);
  font-size: var(--font-size-lg);
  margin-bottom: var(--spacing-md);
  border-bottom: 2px solid var(--color-accent);
  padding-bottom: var(--spacing-sm);
}

.hours-table {
  margin-bottom: var(--spacing-md);
}

.hours-row {
  display: flex;
  justify-content: space-between;
  padding: var(--spacing-sm) 0;
  border-bottom: 1px solid var(--color-border);
}

.hours-row:last-child {
  border-bottom: none;
}

.hours-row .day {
  font-weight: 600;
  color: var(--color-text);
}

.hours-row .time {
  color: var(--color-primary-light);
  font-weight: 600;
}

.hours-note {
  font-size: var(--font-size-sm);
  color: var(--color-text-light);
  font-style: italic;
  margin-bottom: 0;
}

.contact-map {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.contact-map h2 {
  text-align: center;
  margin-bottom: var(--spacing-md);
}

.contact-map > .container > p {
  text-align: center;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-lg);
}

.map-container {
  width: 100%;
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-md);
}

@media (max-width: 600px) {
  .contact-wrapper {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .contact-form-section {
    grid-column: 1;
  }

  .contact-info-section {
    grid-column: 1;
  }

  .contact-form {
    padding: var(--spacing-md);
  }

  .hours-wrapper {
    grid-template-columns: 1fr;
  }

  .hours-row {
    flex-direction: column;
    gap: var(--spacing-xs);
  }

  .map-container {
    min-height: 300px;
  }

  .contact-card {
    margin-bottom: var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .contact-wrapper {
    grid-template-columns: 1fr 1fr;
  }
}
